","customJs":"(() => {
  // Collection cards: when a color swatch changes, point the Wishlist Guru
  // heart at the selected variant and redraw it (filled/empty) for that variant.
  document.addEventListener("change", (event) => {
    const swatch = event.target.closest?.(".color-swatch__radio[data-variant-id]");
    if (!swatch) return;

    const card = swatch.closest("product-item");
    const icon = card?.querySelector(".wf-wishlist");
    if (!icon) return;

    icon.setAttribute("variant-id", swatch.getAttribute("data-variant-id"));

    // Same call Wishlist Guru makes on the product page after a variant change
    if (typeof window.wishlistIcon === "function") {
      window.wishlistIcon();
    }
  });
})();
